tree_node = '''    static class Node { int value; Node left,right; Node(int v){value=v;} }
    static Node sample(){ Node r=new Node(4); r.left=new Node(2); r.right=new Node(6); r.left.left=new Node(1); r.left.right=new Node(3); r.right.left=new Node(5); r.right.right=new Node(7); return r; }
    static void inorder(Node r,List<Integer> out){ if(r!=null){ inorder(r.left,out); out.add(r.value); inorder(r.right,out); } }
    static String view(Node r){ List<Integer> a=new ArrayList<>(); inorder(r,a); return a.toString(); }'''
theory('Introduction to BST', 'A strict BST has every left-subtree value smaller than its root and every right-subtree value larger. This repository uses distinct keys. Inorder traversal is therefore strictly increasing. Search descends only one branch, taking O(h) time where h is height; a skewed tree has h=n, so ordinary BST operations are not automatically logarithmic. Balanced search trees such as TreeMap maintain logarithmic height. Null means an empty tree. Checking only immediate children is insufficient: every descendant must respect all ancestor bounds.')
bst_rows = [
 ('Search in BST','boolean','Node r,int x','while(r!=null){ if(r.value==x) return true; r=x<r.value?r.left:r.right; } return false;','sample(),5','true','Follow the sole possible subtree by comparing the target with each root.'),
 ('Floor and Ceil in a BST','OptionalInt[]','Node r,int x','Integer floor=null,ceil=null; while(r!=null){ if(r.value==x){ floor=ceil=x; break; } if(r.value<x){ floor=r.value; r=r.right; } else { ceil=r.value; r=r.left; } } return new OptionalInt[]{floor==null?OptionalInt.empty():OptionalInt.of(floor),ceil==null?OptionalInt.empty():OptionalInt.of(ceil)};','sample(),4','4 4','Track best smaller and larger values while descending; exact equality gives both answers.'),
 ('Minimum and Maximum in BST','int[]','Node r','if(r==null) throw new IllegalArgumentException(); Node lo=r,hi=r; while(lo.left!=null) lo=lo.left; while(hi.right!=null) hi=hi.right; return new int[]{lo.value,hi.value};','sample()','[1, 7]','The leftmost key is minimum and the rightmost key maximum by the BST ordering invariant.'),
 ('Insert a given node in BST','Node','Node r,int x','if(r==null) return new Node(x); if(x<r.value) r.left=solve(r.left,x); else if(x>r.value) r.right=solve(r.right,x); return r;','sample(),8','[1, 2, 3, 4, 5, 6, 7, 8]','Descend like search; at null create a leaf. Equal keys are ignored under the distinct-key contract.'),
 ('LCA in BST','int','Node r,int a,int b','while(r!=null){ if(a<r.value&&b<r.value) r=r.left; else if(a>r.value&&b>r.value) r=r.right; else return r.value; } throw new IllegalArgumentException();','sample(),1,3','2','Assuming both keys exist, their lowest common ancestor is the first root where their search paths split or one key equals the root.'),
 ('Inorder successor and predecessor in BST','OptionalInt[]','Node r,int x','Integer before=null,after=null; Node p=r; while(p!=null){ if(p.value<x){ before=p.value; p=p.right; } else p=p.left; } p=r; while(p!=null){ if(p.value>x){ after=p.value; p=p.left; } else p=p.right; } return new OptionalInt[]{before==null?OptionalInt.empty():OptionalInt.of(before),after==null?OptionalInt.empty():OptionalInt.of(after)};','sample(),4','3 5','Find strict nearest smaller and strict nearest larger values with two directed searches; x itself need not exist.')]
for title,typ,params,body,call,expected,reason in bst_rows:
    expr='view(solve(%s))'%call if typ=='Node' else 'Arrays.toString(solve(%s))'%call if typ=='int[]' else 'solve(%s)'%call
    example='OptionalInt[] a=solve(%s); System.out.println(a[0].getAsInt()+" "+a[1].getAsInt());'%call if typ=='OptionalInt[]' else 'System.out.println(%s);'%expr
    add(title,tree_node+'\n    public static %s solve(%s){ %s }'%(typ,params,body),example,expected,
        'Operate on a strict BST with distinct int keys. OptionalInt represents missing bounds; node-returning operations mutate links and return the new root.',reason,
        'O(h) time; O(1) auxiliary state for iterative searches, O(h) stack for recursive insertion. h can be n.',
        'Sample BST: root 4; children 2,6; leaves 1,3,5,7. Trace comparisons from root until equality or a null boundary.',
        'The tree must satisfy the whole BST invariant. The LCA method requires both keys present. Do not assume h=log n without balance.')
add('Delete a node in BST',tree_node+'''\n    public static Node solve(Node r,int x){ if(r==null) return null; if(x<r.value) r.left=solve(r.left,x); else if(x>r.value) r.right=solve(r.right,x); else { if(r.left==null) return r.right; if(r.right==null) return r.left; Node successor=r.right; while(successor.left!=null) successor=successor.left; r.value=successor.value; r.right=solve(r.right,successor.value); } return r; }''','System.out.println(view(solve(sample(),4)));','[1, 2, 3, 5, 6, 7]',
    'Delete key x if present, returning the possibly changed root.', 'Zero/one-child deletion replaces root with its child. With two children, copy the smallest right-subtree value and delete that successor; it fits between every left and remaining right key.', 'O(h) time/stack.', 'Delete 4: successor 5 replaces root, then the former leaf 5 is removed from the right subtree.', 'This deletes by key while retaining the root object in the two-child case; external references may observe its changed value.')
add('Kth Smallest and Largest element in BST',tree_node+'''\n    public static int[] solve(Node r,int k){ List<Integer> a=new ArrayList<>(); inorder(r,a); if(k<1||k>a.size()) throw new IllegalArgumentException(); return new int[]{a.get(k-1),a.get(a.size()-k)}; }''','System.out.println(Arrays.toString(solve(sample(),2)));','[2, 6]',
    'Return ONE-based kth smallest and kth largest values, requiring 1<=k<=node count.', 'Inorder gives all keys sorted. Select k-1 from the front and k from the end.', 'O(n) time/space including inorder recursion.', 'Sorted sample 1..7 gives second smallest 2 and second largest 6.', 'A stack iterator can stop early in O(h+k) time and O(h) space. Augment subtree sizes for repeated rank queries.')
add('Check if a tree is a BST or not',tree_node+'''\n    private static boolean valid(Node r,long low,long high){ return r==null || (low<r.value&&r.value<high&&valid(r.left,low,r.value)&&valid(r.right,r.value,high)); }
    public static boolean solve(Node r){ return valid(r,Long.MIN_VALUE,Long.MAX_VALUE); }''','System.out.println(solve(sample()));','true',
    'Validate a strict distinct-key BST; empty is valid.', 'Pass open ancestor bounds recursively. Each node must lie inside both; left tightens upper, right tightens lower. This enforces all ancestor constraints.', 'O(n) time, O(h) stack.', 'Left child 2 has bounds (-infinity,4), its right child 3 has (2,4).', 'Use long bounds so int MIN_VALUE/MAX_VALUE remain valid keys. Immediate-child comparisons alone miss deeper violations.')
add('Construct a BST from a preorder traversal',tree_node+'''\n    private static Node build(int[] a,int[] at,long low,long high){ if(at[0]==a.length||a[at[0]]<=low||a[at[0]]>=high) return null; Node r=new Node(a[at[0]++]); r.left=build(a,at,low,r.value); r.right=build(a,at,r.value,high); return r; }
    public static Node solve(int[] a){ int[] at={0}; Node r=build(a,at,Long.MIN_VALUE,Long.MAX_VALUE); if(at[0]!=a.length) throw new IllegalArgumentException("invalid strict BST preorder"); return r; }''','System.out.println(view(solve(new int[]{4,2,1,3,6,5,7})));','[1, 2, 3, 4, 5, 6, 7]',
    'Build a strict BST from its preorder, rejecting invalid sequences or duplicates.', 'Consume the next preorder key only when inside the current bounds. After root, build left then right with tightened bounds. Each valid key is consumed once.', 'O(n) time, O(h) stack and O(n) output nodes.', '4 becomes root; 2,1,3 fill left; 6,5,7 fill right.', 'Checking only an upper bound can accept some malformed input sequences; both bounds and final consumption validation are used.')
iterator = '''    static class BSTIterator { final Deque<Node> stack=new ArrayDeque<>(); final boolean reverse; BSTIterator(Node root,boolean reverse){ this.reverse=reverse; push(root); } void push(Node r){ while(r!=null){ stack.push(r); r=reverse?r.right:r.left; } } boolean hasNext(){return !stack.isEmpty();} Node nextNode(){ Node r=stack.pop(); push(reverse?r.left:r.right); return r; } int next(){return nextNode().value;} }'''
add('BST iterator',tree_node+'\n'+iterator,'BSTIterator it=new BSTIterator(sample(),false); List<Integer> a=new ArrayList<>(); while(it.hasNext()) a.add(it.next()); System.out.println(a);','[1, 2, 3, 4, 5, 6, 7]',
    'An ascending (or descending with reverse=true) lazy BST iterator; next requires hasNext.', 'Stack contains the path to the next unvisited inorder node. Pop that node and push the opposite subtree\'s boundary path.', 'O(h) storage, O(h) worst per next but O(1) amortized over a full traversal; O(h) initialization.', 'Initially stack is 4,2,1 with 1 on top; pop 1, then 2 pushes 3.', 'Modifying the tree during iteration invalidates the traversal invariant.')
add('Two sum in BST',tree_node+'\n'+iterator+'''\n    public static boolean solve(Node r,long target){ if(r==null) return false; BSTIterator left=new BSTIterator(r,false),right=new BSTIterator(r,true); Node a=left.nextNode(),b=right.nextNode(); while(a!=b){ long sum=(long)a.value+b.value; if(sum==target) return true; if(sum<target){ if(!left.hasNext()) break; a=left.nextNode(); } else { if(!right.hasNext()) break; b=right.nextNode(); } } return false; }''','System.out.println(solve(sample(),9));','true',
    'Find two distinct nodes in a strict BST whose values sum to target.', 'Use ascending and descending iterators like two pointers on sorted values. Move the lower endpoint when sum is low and the upper when high. Stop when node identities meet.', 'O(n) worst time and O(h) auxiliary stack space.', '1+7=8<9, advance low to 2; 2+7=9 succeeds.', 'Compare identities, not values, for distinct-node stopping; strict distinct keys are assumed. Use long sum.')
add('Correct BST with two nodes swapped',tree_node+'''\n    private static void scan(Node r,Node[] state){ if(r==null) return; scan(r.left,state); if(state[0]!=null&&state[0].value>r.value){ if(state[1]==null) state[1]=state[0]; state[2]=r; } state[0]=r; scan(r.right,state); }
    public static void solve(Node r){ Node[] s=new Node[3]; scan(r,s); if(s[1]!=null){ int t=s[1].value; s[1].value=s[2].value; s[2].value=t; } }''','Node r=sample(); int t=r.left.value; r.left.value=r.right.value; r.right.value=t; solve(r); System.out.println(view(r));','[1, 2, 3, 4, 5, 6, 7]',
    'Restore a strict BST whose values in exactly two nodes were swapped. Already-valid input is left unchanged.', 'In inorder, swapped values create one or two descents. Record the previous node at the first descent and the current node at the last descent, then swap them.', 'O(n) time; O(h) stack.', 'Swap 2 and 6: inorder becomes 1,6,3,4,5,2,7; descents identify 6 and 2.', 'This fixes exactly a two-value swap; it is not a general arbitrary-tree BST repair.')
add('Largest BST in Binary Tree',tree_node+'''\n    private static long[] info(Node r){ if(r==null) return new long[]{1,0,Long.MAX_VALUE,Long.MIN_VALUE,0}; long[] l=info(r.left),q=info(r.right); if(l[0]==1&&q[0]==1&&l[3]<r.value&&r.value<q[2]){ long size=1+l[1]+q[1]; return new long[]{1,size,Math.min(l[2],r.value),Math.max(q[3],r.value),size}; } return new long[]{0,0,0,0,Math.max(l[4],q[4])}; }
    public static long solve(Node r){ return info(r)[4]; }''','System.out.println(solve(sample()));','7',
    'Return the number of nodes in the largest rooted subtree that is a strict BST.', 'Postorder returns valid flag, subtree size, minimum, maximum and largest BST size. A root forms a BST iff both children are BSTs and their extrema bracket its key.', 'O(n) time, O(h) stack.', 'Each leaf is a BST size 1; children 2 and 6 each build size 3; root 4 builds size 7.', 'The answer must be a whole rooted subtree, not an arbitrary node subset. Long sentinels preserve extreme int keys.')
